const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountVehicleRegistration(root,api,getUser){
 let epoch=0,busy=false;
 async function refresh(){
  const version=++epoch,u=getUser();root.innerHTML='';if(!u)return;
  root.innerHTML=`<section class="panel"><h2>Register a vehicle</h2><p>Government verification is not connected. Uploaded photos are reviewed privately by the operator; uploading does not verify a document.</p>${u.role!=='driver'?'<p>Your account must be set to Driver. Ask the operator to update your account type.</p>':`<form data-vehicle-form><label>Registration plate<input name="plate" required maxlength="20" placeholder="MH12AB1234"></label><label>Make and model<input name="vehicle" required minlength="2" maxlength="80"></label><label>Services<select name="services"><option value="shared,cab">Shared ride and Car</option><option value="shared">Shared ride</option><option value="cab">Car</option><option value="bike">Bike</option></select></label><label>Driving licence photo<input name="licence_photo" type="file" accept="image/jpeg,image/png" required></label><label>Masked Aadhaar photo<input name="aadhaar_photo" type="file" accept="image/jpeg,image/png" required></label><p>JPG or PNG, up to 2 MB each and 16 megapixels. Hide the first 8 Aadhaar digits before uploading. Do not upload an unmasked Aadhaar card.</p><label class="check-row"><input name="masked_aadhaar" type="checkbox" required>I confirm the first 8 Aadhaar digits are hidden.</label><label class="check-row"><input name="consent" type="checkbox" required>I consent to private operator review of these documents for driver and vehicle eligibility.</label><p>Photos are encrypted in storage, accessible only to the operator for 30 days, then deleted on the next cleanup. Withdrawing a pending application removes its photos. <a href="privacy.html">Privacy details</a></p><button class="button dark">Submit for approval</button></form>`}<p data-vehicle-status role="status"></p><h3>Your submissions</h3><button type="button" class="button outline" data-vehicle-refresh>Refresh submissions</button><div data-vehicle-list>Loading…</div></section>`;
  try{const r=await api.request('/v1/vehicle-applications');if(version!==epoch)return;root.querySelector('[data-vehicle-list]').innerHTML=r.applications.length?r.applications.map(a=>`<article class="panel"><strong>${esc(a.plate)} · ${esc(a.vehicle)}</strong><p>Status: ${esc(a.status)} · Government verification not connected</p><p>${esc(a.review_note)}</p>${a.status==='pending'?`<button type="button" class="button outline" data-withdraw="${esc(a.id)}">Withdraw application</button>`:''}</article>`).join(''):'<p>No submissions yet. Submit the form above to enter the operator’s Vehicle approvals queue.</p>';}catch(e){if(version===epoch)root.querySelector('[data-vehicle-list]').textContent=e.message;}
 }
 const photo=file=>new Promise((resolve,reject)=>{if(!file||!['image/jpeg','image/png'].includes(file.type)||file.size>2*1024*1024){reject(Error('Choose a JPG or PNG photo up to 2 MB.'));return;}const reader=new FileReader();reader.onerror=()=>reject(Error('Could not read photo.'));reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.readAsDataURL(file);});
 root.addEventListener('submit',async e=>{if(!e.target.matches('[data-vehicle-form]'))return;e.preventDefault();if(busy)return;busy=true;const form=e.target,version=epoch,status=root.querySelector('[data-vehicle-status]'),button=form.querySelector('button');button.disabled=true;status.textContent='Uploading securely…';try{const d=new FormData(form);const licence_photo=await photo(d.get('licence_photo')),aadhaar_photo=await photo(d.get('aadhaar_photo'));if(version!==epoch)return;await api.request('/v1/vehicle-applications','POST',{plate:d.get('plate'),vehicle:d.get('vehicle'),services:d.get('services').split(','),licence_photo,aadhaar_photo,consent:d.has('consent'),masked_aadhaar:d.has('masked_aadhaar')});if(version!==epoch)return;form.reset();await refresh();root.querySelector('[data-vehicle-status]').textContent='Submitted. The operator can now review your vehicle and photos.';}catch(error){if(version===epoch)status.textContent=error.message;}finally{busy=false;button.disabled=false;}});
 root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||busy)return;if(b.hasAttribute('data-vehicle-refresh')){void refresh();return;}if(!b.dataset.withdraw||!confirm('Withdraw this pending application and delete its uploaded photos?'))return;busy=true;const version=epoch;try{await api.request('/v1/vehicle-applications/'+b.dataset.withdraw+'/withdraw','POST',{});if(version===epoch)await refresh();}catch(error){if(version===epoch)root.querySelector('[data-vehicle-status]').textContent=error.message;}finally{busy=false;}});
 return {refresh};
}
